@spec arrange_view_spec  src=tests/specs/arrange_view_spec.lua  loc=1289  cases=72
@exercises configManager (h.cm), arrangeView (av), arrangeManager (am), commandManager (h.cmgr)
@surface   cm:set, av:tracksTakes, av:tidyRows, am:resizeTake, am:tracksTakes, cmgr:push, av:cursorRow, av:cursorCol, av:setCursor, av:setBeatPerRow, av:setCursorAt, av:setGridSize, av:scroll, av:scrollBy, av:setMaxCol, av:beatPerRow, cm:get, av:rowToQN, av:paletteSlot, av:setPaletteSlot, am:deleteTake, av:pruneSlots, av:trackSlots, av:seedTidy, av:keyForSlot, av:tidyRenameBase, av:tidyDropBase, av:tidyAddBase, av:tidySlots, av:focus, av:setFocus, cmgr:invoke, av:lassoCandidate, av:selectionSet, av:isSelected, av:selectBand, cmgr:pop, av:dropBand, av:setSelection, av:addToSelection, av:toggleSelected, av:dragCandidate, av:commitDrag, am:loopRangeQN, am:editCursorQN, am:trimHead, av:cursorTake, av:qnToRow
@harness   mk, reaper:setTrackName, reaper:addItem, reaper:setProjectTracks, reaper.GetSetRepeat

# Intent
  arrangeView: in-memory cursor/scroll + persisted beatPerRow, mirroring
  the trackerView/editCursor split (cursor is transient, density persists).

# Helpers
  @fn mkAv(harness)  @ 7-13
  @fn mkArrange(harness, items)  @ 17-38
      -- Build an av over a fake project. items: list of {track, name, pos, len?}.
      -- Tracks are created in first-seen order; beatPerRow is 1 (1 row = 1 QN).
  @fn takeAt(list, startQN)  @ 40-42
  @fn tidySlots(av)  @ 52-55
  @fn tidyPreviews(av, assignment)  @ 57-61
  @fn mkTrimmable(harness)  @ 65-72
      -- One four-row take at rows 2..5, with four rows of source left over: enough
      -- room for the head to walk in and for the tail to grow.

# Cases
  @case 'cursor defaults to (0,0); setCursor clamps negatives and floors'  [harness]  @ 93-101
  @case 'setCursorAt lands the caret on the row holding a project QN'  [harness]  @ 106-113
  @case 'scroll defaults to (0,0); setGridSize alone does not move scroll'  [harness]  @ 117-123
  @case 'cursor moving below the visible band scrolls down to follow'  [harness]  @ 127-134
  @case 'cursor moving above the visible band scrolls up to follow'  [harness]  @ 138-146
  @case 'horizontal follow tracks cursorCol against gridCols'  [harness]  @ 150-160
  @case 'setGridSize shrinking the viewport re-follows the cursor in place'  [harness]  @ 164-175
  @case 'scrollBy pans the viewport without moving the cursor'  [harness]  @ 179-188
  @case 'scrollBy clamps to >= 0 and cursor-nav re-follows the cursor'  [harness]  @ 192-203
  @case 'scroll-right stops once the last column is fully visible'  [harness]  @ 207-215
  @case 'a same-dims setGridSize after a wheel-scroll leaves scroll alone'  [harness]  @ 219-227
  @case 'beatPerRow defaults to cm value; setter clamps minimum'  [harness]  @ 231-240
  @case 'setBeatPerRow holds the cursor QN (zoom anchors on cursor) and clamps max'  [harness]  @ 244-256
  @case 'paletteSlot defaults nil; setter clamps to 0..61; nil clears'  [harness]  @ 260-274
  @case 'a prune takes the palette focus down with the slot it lost'  [harness]  @ 278-290
  @case 'a prune leaves the palette focus alone when its slot still stands'  [harness]  @ 294-305
  @case 'tidyRows joins each MIDI slot to its key, its base and the name a tidy writes'  [harness]  @ 309-324
  @case 'a base rename carries its members, and a rename onto another base merges the two'  [harness]  @ 328-349
  @case 'deleting a base pins its members at the names they hold'  [harness]  @ 353-367
  @case 'an added base takes no members until a row picks it'  [harness]  @ 371-391
  @case 'a tidy renames the track\'s slots, and the palette focus stands'  [harness]  @ 395-411
  @case 'focus defaults nil; setFocus stores an opaque handle, nil clears'  [harness]  @ 415-424
  @case 'no selection + on-screen cursor: edit acts on the cursor take, leaves it unselected'  [harness]  @ 428-444
  @case 'no selection + off-screen cursor: an edit is a no-op'  [harness]  @ 448-464
  @case 'a held selection wins over the cursor take'  [harness]  @ 468-487
  @case 'lasso selects every take whose span intersects the swept rect'  [harness]  @ 491-507
  @case 'Shift+arrow selects every take the anchor-to-cursor rect covers'  [harness]  @ 511-524
  @case 'Shift+arrow sideways widens the rect into the next column'  [harness]  @ 528-539
  @case 'Shift+arrow back toward the anchor drops what it uncovers'  [harness]  @ 543-557
  @case 'a plain cursor move ends the run, so the next Shift+arrow re-anchors'  [harness]  @ 561-573
  @case 'a bare cursor move clears the selection'  [harness]  @ 577-587
  @case 'Home clears the selection like any other bare nav'  [harness]  @ 591-601
  @case 'Tab walks down the column, stopping at each start and each free row after a take'  [harness]  @ 605-623
  @case 'abutting takes collapse their shared boundary to one Tab stop'  [harness]  @ 627-638
  @case 'Shift+Tab walks back up, snapping to the start of the take it is inside'  [harness]  @ 642-656
  @case 'Tab only sees the takes in the cursor column'  [harness]  @ 660-673
  @case 'Tab clears the selection like any other bare nav'  [harness]  @ 677-688
  @case 'an edit's own cursor advance keeps the selection'  [harness]  @ 692-703
  @case 'the pooled duplicate clears the selection and lands the caret on the copy'  [harness]  @ 707-724
  @case 'the band stands through a run and comes down on the next command'  [harness]  @ 728-746
  @case 'a click takes the band down without waiting for a command'  [harness]  @ 750-761
  @case 'dropBand takes the band down and pops its scope'  [harness]  @ 765-775
  @case 'a multi-selection deletes every selected take in one pass'  [harness]  @ 779-793
  @case 'delete and retreat puts the caret on the start row of what is left above it'  [harness]  @ 797-815
  @case 'nudge refuses entirely when any selected take is blocked'  [harness]  @ 819-836
  @case 'nudge slides a contiguous selected block without self-collision'  [harness]  @ 840-855
  @case 'a single-target command no-ops on a multi-selection'  [harness]  @ 859-872
  @case 'arrangeClearSelection empties the selection'  [harness]  @ 876-887
  @case 'addToSelection unions handles without duplicating a present one'  [harness]  @ 891-905
  @case 'toggleSelected adds an absent handle and removes a present one'  [harness]  @ 909-922
  @case 'group drag slides the whole selection by one delta'  [harness]  @ 926-942
  @case 'group drag refuses when a member would hit an outside take'  [harness]  @ 946-959
  @case 'group drag with Alt duplicates the block and reselects the copies'  [harness]  @ 963-981
  @case 'loop to item brackets the take under the arrange cursor'  [harness]  @ 987-1003
  @case 'loop to item takes the selection over the cursor, and spans a block'  [harness]  @ 1007-1024
  @case 'a cursor-driven replace leaves nothing selected'  [harness]  @ 1028-1040
  @case 'a replace of a selected take hands the selection to the replacement'  [harness]  @ 1044-1059
  @case 'a replace of a selection away from the cursor leaves the cursor alone'  [harness]  @ 1063-1075
  @case 'with advance-by-length armed, a drop advances by the take it placed'  [harness]  @ 1081-1094
  @case 'advance-by-length reads the clipped length, not the slot length'  [harness]  @ 1098-1111
  @case 'a second Ctrl-` puts the drop advance back on arrangeAdvanceBy'  [harness]  @ 1115-1129
  @case 'the caret on a start row moves the head down, holding the end still'  [harness]  @ 1136-1145
  @case 'the split key cuts the take at the caret and leaves the caret on the lower half'  [harness]  @ 1149-1159
  @case 'a split on the start row has nothing to cut'  [harness]  @ 1163-1169
  @case 'the caret off the start row moves the tail, leaving the head alone'  [harness]  @ 1173-1182
  @case 'Up on the start row hands back a row of head, taking the caret with it'  [harness]  @ 1186-1196
  @case 'a head at the origin refuses to grow, and the caret holds'  [harness]  @ 1200-1209
  @case 'the take under the cursor carries the source its box hides'  [harness]  @ 1213-1224
  @case 'a head trim is floored at one rendered row'  [harness]  @ 1228-1238
  @case 'a tail shrink never parks the caret on the head row'  [harness]  @ 1242-1255
  @case 'the armed edge is decided once, from the take the caret stands on'  [harness]  @ 1259-1274
  @case 'qnToRow / rowToQN are inverses through beatPerRow'  [harness]  @ 1278-1287

